    /** Is this a code we know? Case-insensitive, because a form is typed in. */
    public static function isValid(string $code): bool
    {
        return isset(self::ALL[strtoupper(trim($code))]);
    }

    /** The stored form of what a person picked, or '' if we do not know it. */
    public static function code(string $code): string
    {
        $code = strtoupper(trim($code));

        return isset(self::ALL[$code]) ? $code : '';
    }

    /** How a code reads on a receipt. Falls back to the code itself. */
    public static function name(string $code): string
    {
        $code = strtoupper(trim($code));

        return self::ALL[$code] ?? $code;
    }

    /**
     * The shop's own country, from settings — the default a checkout selects.
     *
     * A shop mostly sells where it is, so pre-selecting anything else makes
     * every local customer change it. Falls back to Canada, which is where this
     * software is written; the settings screen is one field away.
     */
    public static function shopDefault(): string
    {
        $code = \Cms\Models\Option::get('commerce_country', 'CA') ?? 'CA';

        return self::isValid($code) ? strtoupper($code) : 'CA';
    }
